SELECT CASE WHEN o.channel IN ('mobile', 'web') THEN 'group_a' ELSE 'other' END AS channel_group, YEAR(o.order_date) AS order_year, COUNT(CASE WHEN s.carrier = 'DHL' THEN 1 END) AS dhl_count, AVG(s.cost) AS avg_cost FROM shipments s INNER JOIN orders o ON s.order_id = o.id INNER JOIN stores st ON o.store_id = st.id GROUP BY CASE WHEN o.channel IN ('mobile', 'web') THEN 'group_a' ELSE 'other' END, YEAR(o.order_date) ORDER BY avg_cost DESC;
